/**
 * Certificat d'intégrité cryptographique d'un acte signé (feedback client #1).
 * Retourné par GET /api/portail/integrite/document/{id}/certificat/ (portail
 * client, scopé sur dossier__client=client_lie). Tous les champs sont
 * optionnels et tolérés côté affichage : un certificat partiellement renseigné
 * reste exploitable (empreinte seule, date seule…). Les alias
 * (hash/empreinte, date_scellement/scelle_le, verifie/statut) ainsi que la
 * charge utile réelle (hash_contenu, horodatage_scellement,
 * verification_document, verification_chaine) sont résolus dans le mapper.
 */
export interface CertificatIntegrite {
  /** Empreinte cryptographique (SHA-256) du document signé (hash_contenu). */
  hash?: string;
  /** Empreinte (SHA-256) du dernier bloc de la chaîne (hash_bloc_dernier). */
  hashBloc?: string;
  /** Empreinte actuelle du fichier, recalculée au moment de la vérification. */
  hashFichierActuel?: string;
  /** Nom du document certifié. */
  documentName?: string;
  /** Date de scellement (signature / mise sous scellé). */
  sealedAt?: string;
  /** Client pour qui le certificat a été émis. */
  clientName?: string;
  /** Dossier associé (numéro). */
  dossierNumber?: string;
  /** Confirmation serveur que l'intégrité est vérifiée. */
  verified?: boolean;
  /** Statut texte renvoyé par le serveur (ex: "valide" / "invalide"). */
  status?: string;
  /** Identifiant technique du document source. */
  documentId?: string;
  /** Nom de l'étude émettrice du certificat. */
  etude?: string;
  /** Date de génération du certificat. */
  genereLe?: string;
  /** Nombre de blocs de la chaîne d'intégrité pour ce document. */
  nbBlocs?: number;
  /** La chaîne d'intégrité entière est valide (statut_global === "valide"). */
  chaineValide?: boolean;
}

